# ============================================================
# CELL 4: HAVERSINE DISTANCE FUNCTION
# ============================================================

def haversine_distance(lat1, lon1, lat2, lon2):

    """
    Calculate geographical distance between two coordinates.

    Returns distance in kilometers.
    """

    earth_radius = 6371.0

    lat1 = np.radians(lat1)
    lon1 = np.radians(lon1)

    lat2 = np.radians(lat2)
    lon2 = np.radians(lon2)

    dlat = lat2 - lat1
    dlon = lon2 - lon1

    a = (
        np.sin(dlat / 2) ** 2
        +
        np.cos(lat1)
        *
        np.cos(lat2)
        *
        np.sin(dlon / 2) ** 2
    )

    c = 2 * np.arctan2(
        np.sqrt(a),
        np.sqrt(1 - a)
    )

    distance = earth_radius * c

    return distance


# ============================================================
# CELL 5: GENERATE SYNTHETIC MIGRATION DATA
# ============================================================

def generate_migration_data(
    animals,
    days=120,
    observations_per_animal=40
):

    """
    Generate synthetic migration records.

    Each animal receives:
    - Animal ID
    - Species
    - Date
    - Latitude
    - Longitude
    - Country
    - Habitat
    - Movement distance
    - Movement speed
    """

    records = []

    start_date = datetime(2025, 1, 1)

    animal_counter = 1

    for species, info in animals.items():

        for animal_number in range(1, 6):

            animal_id = f"{species[:3].upper()}-{animal_number:03d}"

            current_lat = info["start_lat"]

            current_lon = info["start_lon"]

            previous_lat = current_lat

            previous_lon = current_lon

            for observation in range(observations_per_animal):

                day_number = int(
                    observation * days / observations_per_animal
                )

                observation_date = (
                    start_date
                    +
                    timedelta(days=day_number)
                )

                # Simulate movement
                movement_lat = np.random.normal(
                    0,
                    info["movement"]
                )

                movement_lon = np.random.normal(
                    0,
                    info["movement"]
                )

                current_lat += movement_lat

                current_lon += movement_lon

                # Keep coordinates inside valid geographic ranges
                current_lat = np.clip(
                    current_lat,
                    -85,
                    85
                )

                current_lon = (
                    (current_lon + 180) % 360
                ) - 180

                distance = haversine_distance(
                    previous_lat,
                    previous_lon,
                    current_lat,
                    current_lon
                )

                # Approximate time between observations
                elapsed_days = max(
                    day_number
                    -
                    (observation - 1) * days / observations_per_animal,
                    0.5
                )

                speed = distance / (elapsed_days * 24)

                records.append({

                    "Animal_ID": animal_id,

                    "Species": species,

                    "Date": observation_date,

                    "Latitude": current_lat,

                    "Longitude": current_lon,

                    "Country": info["country"],

                    "Habitat": info["habitat"],

                    "Distance_km": distance,

                    "Speed_kmh": speed

                })

                previous_lat = current_lat

                previous_lon = current_lon

            animal_counter += 1

    df = pd.DataFrame(records)

    return df


